static char** parse_words(char* s, int* n) {
    int cap = 16;
    char** out = malloc(cap * sizeof(char*));
    *n = 0;
    for (char* w = strtok(s, " \t"); w; w = strtok(NULL, " \t")) {
        if (*n == cap) out = realloc(out, (cap *= 2) * sizeof(char*));
        out[(*n)++] = w;
    }
    return out;
}

int main(void) {
    char* input = read_all();
    int cap = 8;
    g_lines = malloc(cap * sizeof(char*));
    for (char* p = input;;) {
        if (g_count == cap) g_lines = realloc(g_lines, (cap *= 2) * sizeof(char*));
        g_lines[g_count++] = p;
        char* nl = strchr(p, '\n');
        size_t n = nl ? (size_t)(nl - p) : strlen(p);
        if (n && p[n - 1] == '\r') p[n - 1] = '\0';
        if (!nl) break;
        *nl = '\0';
        p = nl + 1;
    }
    int wordsSize = 0;
